// 读取 sales.csv，按商品汇总营业额（小计 = 单价 × 数量），写入 result.json
// 只用 Node.js 内置模块 node:fs，无需安装任何第三方包
// 参考：https://nodejs.org/learn/manipulating-files/reading-files-with-nodejs
import { readFileSync, writeFileSync } from 'node:fs';

const csvPath = new URL('./sales.csv', import.meta.url);
const jsonPath = new URL('./result.json', import.meta.url);

// 按 utf8 读取整个文本文件（fs.readFileSync，同步返回字符串）
const text = readFileSync(csvPath, 'utf8');

const lines = text.split(/\r?\n/).map((l) => l.trim()).filter((l) => l.length > 0);
const header = lines[0].split(',');
const iName = header.indexOf('商品');
const iPrice = header.indexOf('单价');
const iQty = header.indexOf('数量');

if (iName < 0 || iPrice < 0 || iQty < 0) {
  throw new Error(`CSV 表头不符合预期: ${lines[0]}`);
}

const items = [];
const byName = new Map();
let total = 0;

for (const line of lines.slice(1)) {
  const cols = line.split(',');
  const name = cols[iName].trim();
  const price = Number(cols[iPrice]);
  const qty = Number(cols[iQty]);
  if (!name || !Number.isFinite(price) || !Number.isFinite(qty)) continue;

  const subtotal = price * qty;
  const prev = byName.get(name);
  if (prev) {
    prev.数量 += qty;
    prev.小计 = Math.round((prev.小计 + subtotal) * 100) / 100;
  } else {
    const item = { 商品: name, 单价: price, 数量: qty, 小计: subtotal };
    byName.set(name, item);
    items.push(item);
  }
  total += subtotal;
}

const result = {
  明细: items.map((it) => ({ ...it, 小计: Math.round(it.小计 * 100) / 100 })),
  合计: Math.round(total * 100) / 100,
};

writeFileSync(jsonPath, JSON.stringify(result, null, 2) + '\n', 'utf8');

console.log(JSON.stringify(result, null, 2));
